func (this *List) RemoveIndices(indices []int32) {
	this.CheckWidget()
	if indices == (nil) {
		this.Error(ERROR_NULL_ARGUMENT)
	}
	if int32(len(indices)) == 0 {
		return
	}
	var newIndices []int32 = make([]int32, int32(len(indices)))
	copy(newIndices[0:], indices[0:0+int32(len(indices))])
	this.Sort(newIndices)
	var start int32 = newIndices[int32(len(newIndices))-1]
	var end int32 = newIndices[0]
	var count int32 = this.GetItemCount()
	if !(0 <= start && start <= end && end < count) {
		this.Error(ERROR_INVALID_RANGE)
	}
	var iter int64 = gtk.OSG_malloc(int64(gtk.GTKGtkTreeIter_sizeof()))
	var selection int64 = gtk.GTKGtk_tree_view_get_selection(this.Handle)
	gtk.OSG_signal_handlers_block_matched(selection, gtk.OSG_SIGNAL_MATCH_DATA, 0, 0, int64(0), int64(0), int64(WidgetCHANGED))
	var last int32 = -1
	for i := int32(0); i < int32(len(newIndices)); i++ {
		var index int32 = newIndices[i]
		if index != last {
			gtk.GTKGtk_tree_model_iter_nth_child(this.modelHandle, iter, int64(0), index)
			gtk.GTKGtk_list_store_remove(this.modelHandle, iter)
			last = index
		}
	}
	gtk.OSG_signal_handlers_unblock_matched(selection, gtk.OSG_SIGNAL_MATCH_DATA, 0, 0, int64(0), int64(0), int64(WidgetCHANGED))
	gtk.OSG_free(iter)
}

